using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;

    /// <summary>
    /// Maximum number of sentences in the summary (default: 3).
    /// </summary>
    [Range(1, 20)]
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

using System.Text.RegularExpressions;

namespace DocSummary.Services;

public interface IDocumentSummarizer
{
    string Summarize(string documentText, int maxSentences);
}

public partial class DocumentSummarizer : IDocumentSummarizer
{
    public string Summarize(string documentText, int maxSentences)
    {
        var sentences = SplitIntoSentences(documentText);

        if (sentences.Count <= maxSentences)
            return string.Join(" ", sentences);

        var scored = sentences
            .Select((sentence, index) => new
            {
                Sentence = sentence,
                Score = ScoreSentence(sentence, index, sentences)
            })
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => sentences.IndexOf(s.Sentence))
            .Select(s => s.Sentence);

        return string.Join(" ", scored);
    }

    private static List<string> SplitIntoSentences(string text)
    {
        return SentencePattern()
            .Matches(text)
            .Select(m => m.Value.Trim())
            .Where(s => s.Length > 0)
            .ToList();
    }

    private static double ScoreSentence(string sentence, int index, List<string> allSentences)
    {
        var words = WordPattern().Matches(sentence.ToLowerInvariant())
            .Select(m => m.Value)
            .Where(w => w.Length > 3)
            .ToList();

        // Word frequency across the entire document
        var allWords = allSentences
            .SelectMany(s => WordPattern().Matches(s.ToLowerInvariant()).Select(m => m.Value))
            .Where(w => w.Length > 3)
            .GroupBy(w => w)
            .ToDictionary(g => g.Key, g => g.Count());

        double frequencyScore = words.Sum(w => allWords.GetValueOrDefault(w, 0));

        // Boost early sentences (positional bias)
        double positionScore = 1.0 / (index + 1);

        // Prefer medium-length sentences
        double lengthScore = words.Count >= 5 && words.Count <= 30 ? 1.0 : 0.5;

        return frequencyScore * lengthScore + positionScore * 10;
    }

    [GeneratedRegex(@"[^.!?]*[.!?]+", RegexOptions.Compiled)]
    private static partial Regex SentencePattern();

    [GeneratedRegex(@"\w+", RegexOptions.Compiled)]
    private static partial Regex WordPattern();
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly IDocumentSummarizer _summarizer;

    public SummarizeController(IDocumentSummarizer summarizer)
    {
        _summarizer = summarizer;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        var summary = _summarizer.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

